import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:path/path.dart' as path;
import 'package:path_provider/path_provider.dart';
import 'package:song_record/core/theme/app_theme.dart';
import 'package:song_record/features/backup/import/import_decision.dart';
import 'package:song_record/features/backup/import/import_decision_screen.dart';
import 'package:song_record/features/backup/import/import_validation.dart';
import 'package:song_record/features/backup/import/import_zip.dart';

// Independent synthetic ZIP: valid CRC, one deliberately wrong manifest hash.
const archive =
    '';
const owner = '00000000-0000-4000-8000-000000002201';
void main() {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(MaterialApp(theme: AppTheme.dark(), home: const Demo()));
}

class Demo extends StatefulWidget {
  const Demo({super.key});
  @override
  State<Demo> createState() => _State();
}

class _State extends State<Demo> {
  late final ImportDecision controller;
  Directory? root;
  ImportConsent? selected;
  bool cancelled = false;
  @override
  void initState() {
    super.initState();
    controller = ImportDecision(
      validate: validate,
      requireCurrent: () {
        if (!mounted) throw StateError('disposed');
      },
    );
    unawaited(controller.check());
  }

  Future<ValidatedImport> validate(void Function() guard) async {
    guard();
    final cache = await getTemporaryDirectory();
    guard();
    root = await cache.createTemp('import-p22-04-');
    guard();
    final zip = File('${root!.path}/fixture.zip');
    await zip.writeAsBytes(base64Decode(archive));
    guard();
    final staged = await ImportZipReader(
      requireCurrent: guard,
      availableBytes: () async =>
          (await const MethodChannel('com.ksh321.songrecord/recorder_commands')
                  .invokeMethod<num>('availableBackupBytes'))!
              .toInt(),
    ).unpack(zip, root!);
    return ImportValidator(
      owner: owner,
      requireCurrent: guard,
      audio: AndroidImportAudioProbe(),
    ).verify(staged);
  }

  Future<void> cleanup() async {
    final owned = root;
    if (owned == null || !await owned.exists()) return;
    final parent = await getTemporaryDirectory();
    if (path.isWithin(
      await parent.resolveSymbolicLinks(),
      await owned.resolveSymbolicLinks(),
    )) {
      await owned.delete(recursive: true);
    }
  }

  @override
  void dispose() {
    controller.dispose();
    unawaited(cleanup());
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (cancelled || selected != null) {
      return Scaffold(
        appBar: AppBar(title: const Text('P22-04 선택 결과')),
        body: SafeArea(
          child: ListView(
            padding: const EdgeInsets.all(20),
            children: [
              Text(
                cancelled
                    ? '취소 완료 · 기존 데이터 보존'
                    : '별도 부분 미리보기 선택 · 정상 파일 ${selected!.fileIds.length}개 · 오류 파일 1개 제외',
              ),
              const Text('아직 복원하지 않았습니다. 합성 ZIP · 사용자 DB·서버 호출 없음.'),
              if (!cancelled)
                TextButton(
                  onPressed: () {
                    controller.cancel();
                    setState(() {
                      selected = null;
                      cancelled = true;
                    });
                    unawaited(cleanup());
                  },
                  child: const Text('선택 취소'),
                ),
            ],
          ),
        ),
      );
    }
    return ImportDecisionScreen(
      controller: controller,
      onApproved: (choice) {
        controller.requireConsent(choice);
        setState(() => selected = choice);
      },
      onCancel: () {
        setState(() => cancelled = true);
        unawaited(cleanup());
      },
    );
  }
}
